create or replace function public.melrah_dispatch_assign(p_work_order_id uuid,p_resource_id uuid,p_scheduled_start timestamptz default now()) returns uuid language plpgsql security invoker set search_path=public,melrah,core,pg_temp as $$ declare aid uuid; begin if not core.member_of(core.tenant_id('melrah')) then raise exception 'not authorized'; end if; update melrah.work_order set assigned_resource_id=p_resource_id,status='RELEASED',updated_at=now() where id=p_work_order_id; select id into aid from melrah.service_appointment where work_order_id=p_work_order_id and status not in ('COMPLETED','CANCELLED') order by created_at desc limit 1; if aid is null then insert into melrah.service_appointment(work_order_id,resource_id,status,scheduled_start) values(p_work_order_id,p_resource_id,'DISPATCHED',p_scheduled_start) returning id into aid; else update melrah.service_appointment set resource_id=p_resource_id,status='DISPATCHED',scheduled_start=coalesce(scheduled_start,p_scheduled_start),updated_at=now() where id=aid; end if; return aid; end $$; grant execute on function public.melrah_dispatch_assign(uuid,uuid,timestamptz) to authenticated;
